local module = {}
local _rsSprites

local function _loadRS()
    local folder = game.ReplicatedStorage:FindFirstChild("SpriteSheets")
    if folder then
        local sps = {}
        for i, v in pairs(folder:GetChildren()) do
            if v:IsA("ModuleScript") then
                local sp = require(v:Clone())
                for j, k in pairs(sp) do
                    sps[j] = k
                end
            end
        end
        return sps
    end
    return {}
end

function module.LoadModule(moduleScript)
    if moduleScript:IsA("ModuleScript") then
        local sp = require(moduleScript:Clone())
        for j, k in pairs(sp) do
            _rsSprites[j] = k
        end
    end
end

function module.GetSprite(groupName, spriteName)
    if _rsSprites[groupName] and _rsSprites[groupName][spriteName] then
        local img = _rsSprites[groupName][spriteName]
        if not img["Image"] then
            img = {
                Image = img["Image"],
                ImageRectOffset = img["ImageRectOffset"],
                ImageRectSize = img["ImageRectSize"],
            }
        end
        return img
    end
    return nil
end

_rsSprites = _loadRS()
return module